    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    edge, bg = grid[0][0], grid[0][1]
    colors = {v for row in grid for v in row}
    obj = next(v for v in colors if v not in (edge, bg, 8))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    if all(grid[r][0] == edge for r in range(h)):
        left = min(c for r, c in pts)
        # Add a full separator stripe just to the left of the object.
        for r in range(h):
            out[r][left - 1] = 8
    else:
        # Add a full stripe one row above the object.
        top = min(r for r, c in pts)
        for c in range(w):
            out[top - 1][c] = 8
